import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Navigation tree","description":"","frontmatter":{"title":"Navigation tree","covers":{"screens":["SCR-055"],"stories":["US-054"]}},"headers":[],"relativePath":"usage/navigation.md","filePath":"usage/navigation.md"}`),a={name:`usage/navigation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="navigation-tree" tabindex="-1">Navigation tree <a class="header-anchor" href="#navigation-tree" aria-label="Permalink to “Navigation tree”">​</a></h1><p>The navigation tree arranges catalogs in folders, for example <em>IT Landscape &gt; Application Inventory</em>, so that you find the catalog for your task without searching the list of catalogs. Everybody with the permission <code>entity:read</code> (for example the role <code>viewer</code>) sees the tree. Changing it needs the permission <code>viewpoint:manage</code> (role <code>enterprise-architect</code>).</p><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to “The sidebar”">​</a></h2><p>After login, the sidebar on the left of every page shows the tree. It starts at the folder <em>Repository</em>.</p><ul><li><strong>Open and close a folder:</strong> choose the arrow or the name of the folder. The sidebar remembers which folders are open until you close the browser tab.</li><li><strong>Open a catalog:</strong> choose its entry. The catalog opens with its default view, if it has one (see <a href="./catalogs#views">Views</a>).</li><li><strong>Narrow screens:</strong> the sidebar is hidden; the menu button at the left of the header opens it. Choosing a catalog closes it again.</li></ul><p>Folders and catalogs are sorted by name, regardless of upper and lower case. An entry shows its display label if it has one, otherwise the name of the catalog. A person icon marks a personal catalog.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to “Folders”">​</a></h2><p>With <code>viewpoint:manage</code>, the button <em>…</em> next to a folder offers:</p><ul><li><strong>New folder:</strong> creates a folder inside it. Enter a name and choose <em>Create</em>.</li><li><strong>Rename:</strong> changes the name of the folder, the folder <em>Repository</em> included. Its entries and subfolders stay.</li><li><strong>Delete:</strong> asks first and names how many subfolders and entries the deletion removes. The folder is deleted with all its subfolders and entries. <strong>No catalog is deleted</strong>; the catalogs stay in the list of catalogs and in other folders. The folder <em>Repository</em> cannot be deleted.</li></ul><p>A folder name has 1 to 255 characters and is unique within its folder, regardless of upper and lower case; otherwise the dialog says <em>A folder with this name already exists</em>. The tree has at most 10 levels below <em>Repository</em> and at most 500 folders.</p><h2 id="place-a-catalog" tabindex="-1">Place a catalog <a class="header-anchor" href="#place-a-catalog" aria-label="Permalink to “Place a catalog”">​</a></h2><ol><li>Open the catalog and choose <em>Place in navigation</em> (needs <code>viewpoint:manage</code>).</li><li>Under <em>Folder</em>, choose the folder by its path, for example <em>Repository / IT Landscape</em>.</li><li>Optionally, enter a <em>Display label</em>. The tree then shows it instead of the name of the catalog, for example <em>System Inventory</em> for <em>Application Inventory</em>. The catalog keeps its name.</li><li>Choose <em>Place</em>.</li></ol><p>A catalog can be placed in several folders, but only once per folder; a second placement in the same folder says <em>The catalog is already in this folder</em>. A folder has at most 200 entries.</p><h2 id="remove-a-catalog-from-the-tree" tabindex="-1">Remove a catalog from the tree <a class="header-anchor" href="#remove-a-catalog-from-the-tree" aria-label="Permalink to “Remove a catalog from the tree”">​</a></h2><p>With <code>viewpoint:manage</code>, the button <em>×</em> next to an entry removes it from that folder. Only this entry is removed: the catalog itself and its entries in other folders stay.</p><h2 id="personal-catalogs" tabindex="-1">Personal catalogs <a class="header-anchor" href="#personal-catalogs" aria-label="Permalink to “Personal catalogs”">​</a></h2><p>You can place your own personal catalog like a shared one. Only you see its entry: the tree never shows other people&#39;s personal catalogs, so it never leads to a catalog you cannot open. If you later share the catalog, everybody sees the entry.</p><p>Every change of the tree is recorded in the audit trail.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /views/explorer</code> returns the tree from the root as you see it: each folder with <code>id</code>, <code>name</code>, <code>parentId</code>, <code>items</code> and <code>children</code>; each entry with <code>referenceId</code> (the catalog ID), <code>displayLabel</code>, <code>name</code> (the catalog&#39;s current name) and <code>scope</code>.</li><li><code>POST /tree-nodes</code> with <code>name</code> and <code>parentId</code> creates a folder; <code>PATCH /tree-nodes/{nodeId}</code> with <code>name</code> renames it; <code>DELETE /tree-nodes/{nodeId}</code> deletes it.</li><li><code>POST /tree-nodes/{nodeId}/items</code> with <code>itemType: catalog</code>, <code>referenceId</code> and an optional <code>displayLabel</code> places a catalog; <code>DELETE /tree-nodes/{nodeId}/items/{itemId}</code> removes the entry.</li></ul><p>Every change answers with the whole tree. Invalid input is rejected with 422 and names the field in <code>invalidFields</code>, for example <code>name</code> for a taken folder name or <code>referenceId</code> for a second entry in the same folder.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};